 20	json workspace_json(const Workspace::WorkspaceSnapshot& workspace)
 21	{
 22	    json plates = json::array();
 23	    for (const auto& plate : workspace.plates) {
 24	        json objects = json::array();
 25	        for (const auto& object : plate.objects)
 26	            objects.push_back(json{{"id", std::to_string(object.id.value())}, {"name", object.name},
 27	                                   {"instances", object.instances.size()}});
 28	        plates.push_back(json{{"id", std::to_string(plate.id.value())}, {"name", plate.name},
 29	                              {"active", plate.active}, {"sliced", plate.sliced}, {"objects", std::move(objects)}});
 30	    }
 31	    json selected = json::array();
 32	    for (const auto id : workspace.selected_objects)
 33	        selected.push_back(std::to_string(id.value()));
 34	    return json{{"sessionId", std::to_string(workspace.session.value())},
 35	                {"revision", workspace.revision},
 36	                {"projectName", workspace.setup.project_name},
 37	                {"printerPreset", workspace.setup.printer_preset},
 38	                {"filamentPreset", workspace.setup.filament_preset},
 39	                {"selectedObjectIds", std::move(selected)},
 40	                {"plates", std::move(plates)}};
 41	}
 42	
 43	bool available_in_app(const ToolDefinition& definition, bool allow_import, const std::vector<std::string>& session_tools)
 44	{
 45	    // A session with a subject of its own offers exactly the tools it names,
 46	    // and those may be its own rather than the app's.
 47	    if (!session_tools.empty())
 48	        return std::find(session_tools.begin(), session_tools.end(), definition.name) != session_tools.end() &&
 49	               (has_exposure(definition.exposure, ToolExposure::InApp) || has_exposure(definition.exposure, ToolExposure::Printer));
 50	    return has_exposure(definition.exposure, ToolExposure::InApp) &&
 51	           (definition.availability == ToolAvailability::Always || allow_import);
 52	}
 53	
 54	bool has_closed_required_objects(const json& schema)
 55	{
 56	    if (schema.value("type", json()) == "object") {
 57	        if (schema.value("additionalProperties", json()) != false)
 58	            return false;
 59	        const auto properties = schema.value("properties", json::object());
 60	        const auto required = schema.value("required", json::array());
 61	        for (const auto& property : properties.items())
 62	            if (std::find(required.begin(), required.end(), property.key()) == required.end() ||
 63	                !has_closed_required_objects(property.value()))
 64	                return false;
 65	    }
 66	    return !schema.contains("items") || has_closed_required_objects(schema["items"]);
 67	}
 68	
 69	struct DeferredToolset
 70	{
 71	    const char* name;
 72	    const char* description;
 73	    std::vector<ToolHandler> handlers;
 74	};
 75	
 76	const std::vector<DeferredToolset>& deferred_toolsets()
 77	{
 78	    // The guide's toolsets, with four frequent reads left eager. Empty future
 79	    // toolsets (machine and calibration) are not advertised.
 80	    static const std::vector<DeferredToolset> sets{
 81	        {"core", "Analyze object geometry, preview and apply settings, record print intent and plans, start slicing, and read slice reports.",
 82	         {ToolHandler::ObjectAnalyze, ToolHandler::SettingsPreviewPatch, ToolHandler::SettingsApplyPatch,
 83	          ToolHandler::IntentUpdate, ToolHandler::PlanSet, ToolHandler::SliceStart, ToolHandler::SliceReportRead}},
 84	        {"project", "Open or create a project and read its attachments.",
 85	         {ToolHandler::ProjectOpen, ToolHandler::AttachmentRead}},
 86	        {"setup", "Find presets and printers, preview and change the project's printer and filament setup.",
 87	         {ToolHandler::PresetsList, ToolHandler::PrinterList, ToolHandler::PrinterSetupPreview, ToolHandler::PrinterSetup}},
 88	        {"geometry", "Place objects, arrange plates, import attached models, and delete project items.",
 89	         {ToolHandler::ObjectPlace, ToolHandler::PlateLayout, ToolHandler::ObjectImport, ToolHandler::ProjectDeleteItems}},
 90	        {"reshape", "Preview cuts, cut or split objects, merge objects, and repair meshes.",
 91	         {ToolHandler::ObjectDividePreview, ToolHandler::ObjectDivide, ToolHandler::ObjectMerge, ToolHandler::ObjectRepair}},
 92	        {"regions", "Annotate local object regions with printing requirements such as support, strength or surface finish.",
 93	         {ToolHandler::RegionAnnotate}},
 94	        {"check", "Render a view, inspect sliced layers or G-code, and cancel an activity.",
 95	         {ToolHandler::ViewRender, ToolHandler::SliceInspect, ToolHandler::ActivityCancel}},
 96	        {"output", "Export G-code, sliced or project 3MF, STL, or preset bundles to a file.",
 97	         {ToolHandler::ExportFile}}
 98	    };
 99	    return sets;
100	}
101	
102	const DeferredToolset* deferred_toolset(ToolHandler handler)
103	{
104	    for (const auto& set : deferred_toolsets())
105	        if (std::find(set.handlers.begin(), set.handlers.end(), handler) != set.handlers.end())
106	            return &set;
107	    return nullptr;
108	}
109	
110	json tools_for(ToolSearch search, const std::vector<std::string>& session_tools)
111	{
112	    json tools = json::array();
113	    json namespaces = json::object();
114	    for (const ToolDefinition& definition : ToolRegistry::instance().definitions()) {
115	        // Availability still gates execution. Advertising import consistently
116	        // avoids changing the cached tools prefix when an attachment is added.
117	        if (!available_in_app(definition, true, session_tools))
118	            continue;
119	        json tool{{"type", "function"},
120	                             {"name", definition.name},
121	                             {"description", definition.description},
122	                             // OpenAI strict mode cannot express optional
123	                             // fields or dynamic maps. Preserve the registry
124	                             // schema; native validation still owns acceptance.
125	                             {"strict", has_closed_required_objects(definition.input_schema)},
126	                             {"parameters", definition.input_schema}};
127	        const auto* set = deferred_toolset(definition.handler);
128	        if (search != ToolSearch::None && set != nullptr)
129	            tool["defer_loading"] = true;
130	        if (search == ToolSearch::Namespaces && set != nullptr) {
131	            if (!namespaces.contains(set->name))
132	                namespaces[set->name] = json{{"type", "namespace"}, {"name", set->name},
133	                                            {"description", set->description}, {"tools", json::array()}};
134	            namespaces[set->name]["tools"].push_back(std::move(tool));
135	        } else {
136	            tools.push_back(std::move(tool));
137	        }
138	    }
139	    for (const auto& entry : namespaces.items())
140	        tools.push_back(entry.value());
141	    if (search != ToolSearch::None)
142	        tools.push_back(json{{"type", "tool_search"}});
143	    return tools;
144	}
145	
146	} // namespace
147	
148	std::optional<ToolSearch> parse_tool_search(const std::string& value)
149	{
150	    if (value.empty() || value == "none")
151	        return ToolSearch::None;
152	    if (value == "functions")
153	        return ToolSearch::Functions;
154	    if (value == "namespaces")
155	        return ToolSearch::Namespaces;
156	    return std::nullopt;
157	}
158	
159	std::optional<ToolSearch> resolve_tool_search(const std::string& setting, const OpenAIResponsesConfig& route)
160	{
161	    if (!setting.empty())
162	        return parse_tool_search(setting);
163	    const OpenAIResponsesConfig builtin;
164	    return route.model == builtin.model && route.endpoint == builtin.endpoint ? ToolSearch::Namespaces : ToolSearch::None;
165	}
