167	OpenAIResponsesAgent::OpenAIResponsesAgent(OpenAIResponsesConfig config,
168	                                           std::unique_ptr<IAgentHttpTransport> transport)
169	    : m_config(std::move(config)), m_transport(std::move(transport))
170	{}
171	
172	OpenAIResponsesAgent::~OpenAIResponsesAgent() { cancel(); }
173	
174	bool OpenAIResponsesAgent::ready() const
175	{
176	    return m_transport != nullptr && !m_config.api_key.empty() && !m_config.model.empty() && !m_config.endpoint.empty();
177	}
