    33	AgentRuntime load_agent_runtime(AppConfig* config)
    34	{
    35	    AgentRuntime runtime;
    36	    runtime.setup = make_agent_setup(config);
    37	    runtime.provider = config == nullptr ? std::string() : config->get(kSection, "provider");
    38	    if (runtime.provider.empty())
    39	        runtime.provider = "openai";
    40	
    41	    if (!configured_true(config, "enabled")) {
    42	        runtime.unavailable_reason = "The Agent is not enabled.";
    43	        return runtime;
    44	    }
    45	    if (runtime.provider != "openai") {
    46	        runtime.unavailable_reason = "The configured Agent provider is not supported.";
    47	        return runtime;
    48	    }
    49	    if (!configured_true(config, "cloud_consent")) {
    50	        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
    51	        return runtime;
    52	    }
    53	
    54	    OpenAIResponsesConfig openai;
    55	    openai.api_key = load_provider_api_key(config, runtime.provider);
    56	    if (config != nullptr && !config->get(kSection, "model").empty())
    57	        openai.model = config->get(kSection, "model");
    58	    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint != nullptr && *endpoint != '\0')
    59	        openai.endpoint = endpoint;
    60	    std::string search_setting = config == nullptr ? std::string() : config->get(kSection, "tool_search");
    61	    if (const char* search = std::getenv("JUSPRIN_AGENT_TOOL_SEARCH"); search != nullptr)
    62	        search_setting = search;
    63	    const auto search = resolve_tool_search(search_setting, openai);
    64	    if (!search) {
    65	        runtime.unavailable_reason = "Unknown tool search capability. Use none, functions, or namespaces.";
    66	        return runtime;
    67	    }
    68	    openai.tool_search = *search;
    69	    // Refused tool calls never reach a card or the activity list; the log is
    70	    // where a wrong call can be read afterwards.
    71	    openai.refusal_listener = [](const std::string& tool, const std::string& arguments, const std::string& code) {
    72	        BOOST_LOG_TRIVIAL(warning) << "Agent tool call refused (" << code << "): " << tool << " " << arguments.substr(0, 1024);
    73	    };
    74	    if (openai.api_key.empty()) {
    75	        runtime.unavailable_reason = "No OpenAI API key is configured.";
    76	        return runtime;
    77	    }
    78	    runtime.service = std::make_unique<OpenAIResponsesAgent>(std::move(openai), make_openai_http_transport());
    79	    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
    80	    if (runtime.availability == AgentAvailability::Unavailable)
    81	        runtime.unavailable_reason = "The OpenAI Agent could not be initialized.";
    82	    return runtime;
    83	}
