    85	AgentSetupServicePtr make_agent_setup(AppConfig* config)
    86	{
    87	    // Committing is the only part of setup that touches the machine, so it
    88	    // lives here rather than in the GUI-free probe. Reaching this point means
    89	    // the user read what the dock says about the provider billing them and
    90	    // about the key staying on this machine, and chose to continue: that is
    91	    // the cloud consent load_agent_runtime() requires on the next launch.
    92	    auto commit = [config](const SetupCredentials& credentials) {
    93	        if (config == nullptr || credentials.provider.empty() || credentials.api_key.empty())
    94	            return false;
    95	        config->set(kSection, api_key_item_for(credentials.provider), credentials.api_key);
    96	        config->set(kSection, "provider", credentials.provider);
    97	        config->set(kSection, "enabled", "true");
    98	        config->set(kSection, "cloud_consent", "true");
    99	        if (!credentials.model.empty())
   100	            config->set(kSection, "model", credentials.model);
   101	        // Written now, not at the next routine save, so a crash after setup
   102	        // does not lose a key the user was just told is stored.
   103	        config->save();
   104	        return true;
   105	    };
   106	    std::string endpoint_override;
   107	    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint != nullptr && *endpoint != '\0')
   108	        endpoint_override = endpoint;
   109	    return std::make_shared<ProviderKeySetup>(&make_openai_http_transport, std::move(commit),
   110	                                              std::move(endpoint_override));
   111	}
