# Runs one arm of journeys with the deferral-fix build (C:\b\dfx), one harness at a time.
#   run-dfx.ps1 -Arm fixed-functions                       DeepSeek on OpenRouter, the app's default loading for that route
#   run-dfx.ps1 -Arm fixed-app -Route app                  gpt-5.4-mini on OpenAI, namespaces (the app's own route)
#   run-dfx.ps1 -Arm xyz -ToolSearch none                  JUSPRIN_AGENT_TOOL_SEARCH override
# Records land in <Out>\<Arm>\<scenario>-<n>.json beside a .log. A run whose record exists is skipped.
param(
    [Parameter(Mandatory)][string]$Arm,
    [string]$Route = 'openrouter',
    [string]$ToolSearch = '',
    [string]$Experiment = '',
    [int]$Runs = 3,
    [string[]]$Scenarios = @('petg-question', 'what-is-this', 'desk-ornament', 'outdoor-fitting'),
    [string]$Worktree = 'C:\src\JusPrin\.claude\worktrees\great-nightingale-58f301',
    [string]$Exe = 'C:\b\dfx\tests\shell\Release\shell_integration_harness.exe',
    [string]$Out = "$PSScriptRoot\runs",
    [double]$BudgetUsd = 2.00
)
$scenarioDir = Join-Path $Worktree 'tests\project_journey\scenarios'
$dir = Join-Path $Out $Arm
$status = Join-Path $dir '_status.txt'
New-Item -ItemType Directory -Force $dir | Out-Null
Remove-Item $status -ErrorAction SilentlyContinue
function Finish([string]$message, [int]$code) { Set-Content $status $message; $message; exit $code }

# List prices, no discount for cached input, so this overstates.
$priceIn = if ($Route -eq 'app') { 0.75 } else { 0.091 }
$priceOut = if ($Route -eq 'app') { 4.50 } else { 0.182 }
function Spent {
    $in = 0; $outTokens = 0
    Get-ChildItem $dir -Filter *.log -ErrorAction SilentlyContinue | ForEach-Object {
        Select-String -Path $_.FullName -Pattern 'LIVE USAGE .*input_tokens=(\d+) cached_input_tokens=\d+ output_tokens=(\d+)' | ForEach-Object {
            $in += [int64]$_.Matches[0].Groups[1].Value; $outTokens += [int64]$_.Matches[0].Groups[2].Value
        }
    }
    [pscustomobject]@{ Input = $in; Output = $outTokens; Usd = [math]::Round($in * $priceIn / 1e6 + $outTokens * $priceOut / 1e6, 3) }
}

$keyName = if ($Route -eq 'app') { 'OPENAI_API_KEY' } else { 'OPENROUTER_API_KEY' }
$line = Get-Content "$HOME\.config\jusprin\prompt-test.env" | Where-Object { $_ -match "^(export )?$keyName=" } | Select-Object -First 1
Set-Item -Path "env:$keyName" -Value (($line -replace "^(export )?$keyName=", '').Trim().Trim('"').Trim("'"))
if ($Route -eq 'app') { $env:JUSPRIN_JOURNEY_ROUTE = 'app' } else { Remove-Item env:JUSPRIN_JOURNEY_ROUTE -ErrorAction SilentlyContinue }
if ($ToolSearch) { $env:JUSPRIN_AGENT_TOOL_SEARCH = $ToolSearch } else { Remove-Item env:JUSPRIN_AGENT_TOOL_SEARCH -ErrorAction SilentlyContinue }
$env:WEBVIEW2_USER_DATA_FOLDER = "C:\Users\guitest\AppData\Local\Temp\claude\jw-dfx-$Arm"

foreach ($i in 1..$Runs) {
    foreach ($name in $Scenarios) {
        $record = Join-Path $dir "$name-$i.json"; $log = Join-Path $dir "$name-$i.log"
        if (Test-Path $record) { "$Arm $name-$i already recorded"; continue }
        $spent = Spent
        if ($spent.Usd -ge $BudgetUsd) { Finish "STOPPED: this arm has spent about `$$($spent.Usd) of its `$$BudgetUsd ($($spent.Input) input, $($spent.Output) output tokens)" 5 }
        $arguments = @('--journey', (Join-Path $scenarioDir "$name.json"), $record)
        if ($Experiment) { $arguments += @('--journey-experiment', $Experiment) }
        & $Exe @arguments 2> $log
        $code = $LASTEXITCODE
        $summary = (Select-String -Path $log -Pattern 'HARNESS JOURNEY' | Select-Object -Last 1).Line
        $problem = (Select-String -Path $log -Pattern 'HARNESS ERROR' | Select-Object -Last 1).Line
        "$Arm $name-$i exit=$code $summary $problem"
        if (Select-String -Path $log -Pattern 'status=(401|402|403|429)' -Quiet) { Finish 'STOPPED: the provider refused the key or the quota' 4 }
        if (Select-String -Path $log -Pattern 'HARNESS ERROR journey experiment' -Quiet) { Finish 'STOPPED: the experiment file does not apply' 6 }
    }
}
$spent = Spent
Finish "$Arm done: about `$$($spent.Usd) ($($spent.Input) input, $($spent.Output) output tokens)" 0

